const crypto = require('crypto');
const body = $input.first().json.body || $input.first().json;
const clinicId = $env.VOICEAI_CLINIC_ID;
const secret = $env.VOICEAI_N8N_SECRET;
const entries = Array.isArray(body.entry) ? body.entry : [];
const statuses = [];

for (const entry of entries) {
  for (const change of (entry.changes || [])) {
    for (const st of (change.value?.statuses || [])) {
      if (st.id && st.status) {
        statuses.push({ providerMessageId: st.id, status: st.status });
      }
    }
  }
}

if (statuses.length === 0) return [];

const rawBody = JSON.stringify({ statuses });
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex');

return [{ json: { clinicId, rawBody, timestamp, signature } }];
